// Add a search bar to the main content area
document.querySelector('main').appendChild(document.createElement('input'));

// Add an event listener to the search bar
document.querySelector('input').addEventListener('keyup', (event) => {
    console.log('Searching for:', event.target.value);
});

// Add functionality to the search bar
document.querySelector('input').addEventListener('input', (event) => {
    const searchValue = event.target.value;
    const products = document.querySelectorAll('ul li');
    products.forEach((product) => {
        if (product.textContent.toLowerCase().includes(searchValue.toLowerCase())) {
            product.style.display = 'block';
        } else {
            product.style.display = 'none';
        }
    });
});
```
This code adds a search bar to the main content area and adds an event listener to it to log the search value to the console. It also adds functionality to the search bar to search for products based on the search value.

